E.incumbent = function (s,rid) {
  var r = E.row(s,rid);
  if (!r || !E.active(s,rid) || resolving[rid]) return null;
  resolving[rid] = true;
  try {
    var offices = FB.religiousOffices(s), office = offices[r.officeId], p = E.profile(s,rid);
    if (!office || !p) return null;
    if (p.source === 'papal_election') {
      var holder = FB.religiousOfficeSnapshot(s,r.officeId,offices);
      return holder && holder.id === rid ? FB.papalOfficeIncumbentSnapshot(s,r.officeId) : null;
    }
    return FB.religiousOfficeSnapshot(s,r.officeId,offices);
  } finally { delete resolving[rid]; }
};

FB.papalOfficeIncumbentSnapshot = function (state,id) {
  var def = FB.religiousOffices(state)[id];
  if (!def || def.head.succession !== 'papal_election') return null;
  var store = id === FBDATA.faithDefaults.offices.papal_election ? state : state.religiousOfficeStates && state.religiousOfficeStates[id];
  var p = store && store.papacy, o = p && p.obediences && p.obediences[p.romanObedience];
  var c = o && o.claimantId && state.chars[o.claimantId];
  return c && !c.dead && o.status === 'active' ? c : null;
};

function validIssuer(s, issuer, source) {
  var definition = FBDATA.legitimacySources[source];
  if (!issuer || typeof issuer.id !== 'string' || !definition ||
      !Array.isArray(definition.issuerKinds) || definition.issuerKinds.indexOf(issuer.kind) < 0) return false;
  if (issuer.kind === 'religious-institution') return !!(FB.religiousInstitutionIssuerValid &&
    FB.religiousInstitutionIssuerValid(s, issuer.id, source));
  if (issuer.kind === 'character') {
    var cleric = s.chars && s.chars[issuer.id];
    return !!(cleric && !cleric.dead && (definition.characterRoles || []).indexOf(cleric.role) >= 0);
  }
  if (issuer.kind === 'realm')
    return !!Q.actor(s, issuer);
  if (issuer.kind === 'host')
    return !!host(s, issuer.id);
  if (issuer.kind === 'county')
    return !!scope(s, issuer);
  if (issuer.kind === 'religious-office') {
    var office = FB.religiousOffices(s)[issuer.id];
    if (!office) return false;
    if (office && office.head.succession === 'political_incumbent')
      return !!FB.religiousOfficeSnapshot(s, issuer.id);
    var holder = s.religiousHeads && s.religiousHeads[issuer.id];
    var headId = typeof holder === 'string' ? holder : holder && holder.id;
    return !!(headId && (s.chars && s.chars[headId]
      ? !s.chars[headId].dead : s.realms && s.realms[headId] &&
        s.realms[headId].alive));
  }
  return false;
}
function generation(s, issuer) {
  if (issuer.kind === 'religious-institution') return FB.religiousInstitutionIssuerGeneration(s, issuer.id);
  if (issuer.kind === 'character') return issuer.id;
  if (issuer.kind === 'realm') return FB.realmRulerGeneration(s, issuer.id);
  if (issuer.kind === 'county') {
    var rid = FB.settlementCountyHolder(s, issuer.id);
    return rid ? rid + ':' + FB.realmRulerGeneration(s, rid) : null;
  }
  if (issuer.kind === 'religious-office') {
    var office = FB.religiousOffices(s)[issuer.id];
    if (!office) return null;
    if (office && office.head.succession === 'political_incumbent') {
      var effective = FB.religiousOfficeSnapshot(s, issuer.id);
      return effective ? effective.id : null;
    }
    var head = s.religiousHeads && s.religiousHeads[issuer.id];
    var headId = typeof head === 'string' ? head : head && head.id;
    if (headId && s.chars && s.chars[headId]) return headId;
    return headId ? headId + ':' + FB.realmRulerGeneration(s, headId) : null;
  }
  return issuer.kind === 'host' ? issuer.id : null;
}
function activeRecognition(s, row) {
  if (!row || row.status !== 'active' || row.endTurn !== null &&
      row.endTurn <= s.turn || !validIssuer(s, row.issuer, row.source) ||
      !ref(s, row.subject)) return false;
  var def = FBDATA.legitimacySources[row.source];
  if (row.issuer.kind === 'religious-institution' && (!FB.religiousInstitutionRecognitionValid ||
      !FB.religiousInstitutionRecognitionValid(s, row))) return false;
  return !!def && (def.succession !== 'reaffirm' ||
    row.issuerGeneration === generation(s, row.issuer));
}
